  "answer": "Our top customer by total spending is Helena Holý (CustomerId 6). She spent $49.62 across 7 invoices. Her first invoice in the system is 2009-07-11 and her most recent is 2013-11-13. Contact/email on file: hholy@gmail.com. Country: Czech Republic.",
  "sql_used": [
    "WITH totals AS (\n SELECT c.CustomerId, c.FirstName, c.LastName, c.Email, c.Company, c.Country,\n       SUM(i.Total) AS TotalSpent, COUNT(i.InvoiceId) AS InvoiceCount,\n       MIN(i.InvoiceDate) AS FirstInvoice, MAX(i.InvoiceDate) AS LastInvoice\n FROM Customer c\n JOIN Invoice i ON i.CustomerId = c.CustomerId\n GROUP BY c.CustomerId\n)\nSELECT *\nFROM totals\nWHERE TotalSpent = (SELECT MAX(TotalSpent) FROM totals);"
  ],
  "assumptions": [
    "Interpreted \"best customer\" as the customer with the highest total spending (sum of Invoice.Total)."
  ],
  "confidence": "high",
  "answerable": true
}

